  function gameStateLabel(game) {

    var now = nowMinutes();
    var visible = game.visibleFrom ? A.wallMinutes(game.visibleFrom) : null;
    var start = A.wallMinutes(game.startAt);
    var end = A.wallMinutes(game.endAt, true);

    if (visible !== null && now < visible) return A.chip('مستخبية لحد ' + A.formatWall(game.visibleFrom), 'off');
    if (start !== null && now < start) return A.chip('قريبًا — تبدأ ' + A.formatWall(game.startAt), 'gold');
    if (end !== null && now < end) return A.chip('🔥 شغالة دلوقتي', 'ok');
    return A.chip('انتهت', 'off');

  }

