    var list = el('ul', { class: 'acts', 'aria-busy': 'true', 'aria-label': 'سجل النشاط' });
    var more = el('button', { class: 'btn btn--ghost', type: 'button', hidden: true, text: 'اعرض أقدم' });
    var next = 0;
    var drawn = [];
    var refreshed = false;
    var loading = 0;
    var focus = focusId;
    var gone = goneNote;

    // once: a link opened this page for one entry / a gone item
    focusId = '';
    goneNote = null;

    var people = [{ key: '', label: 'كل الأدمنز' }].concat(Object.keys(A.state.names || {}).map(function (email) {
      return { key: email, label: A.state.names[email] };
    }));

