    if (!list.length || !A.state) return;

    // the home card and the log show them too
    var activity = A.state.activity || (A.state.activity = { recent: [] });
    var ids = list.map(function (e) { return e.id; });
    activity.recent = list.slice().reverse().concat((activity.recent || []).filter(function (e) { return ids.indexOf(e.id) === -1; })).slice(0, 6);
